import{_ as i,o as r,a as t,b as o}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子实现","link":"/guide/operator_practice/simd_operator_impl/simd_operator_impl"},{"text":"概述","link":"/guide/operator_practice/simd_operator_impl/overview"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_impl/overview.md","filePath":"guide/operator_practice/simd_operator_impl/overview.md","lastUpdated":1787050286000}'),a={name:"guide/operator_practice/simd_operator_impl/overview.md"};function p(_,e,n,l,d,s){return r(),t("div",null,[...e[0]||(e[0]=[o('<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000002500548086"></span></h1><p>Ascend C的算子实现主要包含两个部分：</p><ul><li><p>Host侧Tiling实现</p><p>由于NPU中AI Core内部存储无法完全容纳算子输入输出的所有数据，需要每次搬运一部分输入数据进行计算然后搬出，再搬运下一部分输入数据进行计算，这个过程就称之为Tiling。切分数据的算法称为Tiling算法或者Tiling策略。根据算子的shape等信息来确定数据切分算法相关参数（比如每次搬运的块大小，以及总共循环多少次）的计算程序，称之为Tiling实现，也叫Tiling函数（Tiling Function）。由于Tiling实现中完成的均为标量计算，AI Core并不擅长，所以我们将其独立出来放在Host侧CPU上执行。</p></li><li><p>Device侧核函数（Kernel）实现</p><p>算子核函数（Kernel）实现中，通过解析Host侧传入的Tiling结构体获取Tiling信息，根据Tiling信息控制数据搬入搬出Local Memory的流程；通过调用计算、数据搬运、内存管理、任务同步API，实现算子逻辑。其核心逻辑基本上都为计算密集型任务，需要在NPU上执行。</p></li></ul><p>本章介绍矢量编程、矩阵编程、融合算子编程三种典型场景下的算子Tiling、核函数（Kernel）实现，是对上文中典型<a href="../../programming_guide/programming_model/ai_core_simd_programming/overview.html">编程范式</a>的具体应用，同时也介绍了编程的更多细节、API的使用方法等。</p></article></div>',1)])])}const g=i(a,[["render",p]]);export{m as __pageData,g as default};
